import copy
import json
import math
import sys

REQUIRED_KINDS = {"application", "gateway", "provider", "retrieval", "tool", "postcondition"}
INFRA_KINDS = {"gateway", "provider", "retrieval", "tool"}
BASE_FIELDS = {"trace_id", "span_id", "parent_span_id", "kind", "latency_ms", "quality", "cost_usd", "status"}
STATUSES = {"ok", "error"}
TOLERANCE = 1e-9

EXPECTED_STDOUT = """candidate=Northstar TraceHub hard_gate=PASS request_p50_ms=500.000 request_p95_ms=590.000 request_p99_ms=598.000 span_p50_ms=50.000 span_p95_ms=480.000 span_p99_ms=576.000 quality=0.950 infra=0.778 cost_usd=0.550 score=0.798
candidate=OpenRelay hard_gate=PASS request_p50_ms=500.000 request_p95_ms=545.000 request_p99_ms=549.000 span_p50_ms=50.000 span_p95_ms=495.000 span_p99_ms=539.000 quality=0.750 infra=1.000 cost_usd=0.400 score=0.795
selected=Northstar TraceHub
negative=negative_latency result=REJECT
negative=bool_latency result=REJECT
negative=nonfinite_latency result=REJECT
negative=negative_cost result=REJECT
negative=unbounded_quality result=REJECT
negative=invalid_status result=REJECT
negative=missing_provider_span result=REJECT
negative=duplicate_span_id result=REJECT
negative=broken_parent result=REJECT
negative=unknown_retry_target result=REJECT
negative=malformed_record result=REJECT
negative=misleading_aggregate result=REJECT
negative=privacy_gate result=REJECT
negative=export_gate result=REJECT
negative=tenant_gate result=REJECT"""


def number(value, field, minimum=None, maximum=None):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(field + "_not_number")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError(field + "_not_finite")
    if minimum is not None and value < minimum:
        raise ValueError(field + "_below_minimum")
    if maximum is not None and value > maximum:
        raise ValueError(field + "_above_maximum")
    return value


def percentile(values, q):
    if not values:
        raise ValueError("empty_percentile_input")
    ordered = sorted(values)
    rank = (len(ordered) - 1) * q
    lower = math.floor(rank)
    upper = math.ceil(rank)
    if lower == upper:
        return ordered[lower]
    fraction = rank - lower
    return ordered[lower] + fraction * (ordered[upper] - ordered[lower])


def validate_records(candidate, required_kinds):
    records = candidate.get("records")
    if not isinstance(records, list) or not records:
        raise ValueError("records_empty_or_malformed")

    ids = {}
    positions = {}
    by_trace = {}
    span_latencies = []
    request_latencies = []
    postcondition_qualities = []
    infra_count = 0
    infra_errors = 0
    total_cost = 0.0

    for position, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError("record_not_object")
        allowed = BASE_FIELDS | {"retry_of"}
        if set(record) not in (BASE_FIELDS, allowed):
            raise ValueError("record_fields_invalid")

        trace_id = record["trace_id"]
        span_id = record["span_id"]
        parent_id = record["parent_span_id"]
        kind = record["kind"]
        status = record["status"]

        if not isinstance(trace_id, str) or not trace_id:
            raise ValueError("trace_id_invalid")
        if not isinstance(span_id, str) or not span_id:
            raise ValueError("span_id_invalid")
        if span_id in ids:
            raise ValueError("duplicate_span_id")
        if parent_id is not None and (not isinstance(parent_id, str) or not parent_id):
            raise ValueError("parent_span_id_invalid")
        if kind not in required_kinds:
            raise ValueError("span_kind_invalid")
        if status not in STATUSES:
            raise ValueError("status_invalid")

        latency = number(record["latency_ms"], "latency_ms", minimum=0.0)
        quality = number(record["quality"], "quality", minimum=0.0, maximum=1.0)
        cost = number(record["cost_usd"], "cost_usd", minimum=0.0)
        if kind != "postcondition" and quality != 0.0:
            raise ValueError("infrastructure_quality_must_be_zero")

        ids[span_id] = record
        positions[span_id] = position
        by_trace.setdefault(trace_id, []).append(record)
        span_latencies.append(latency)
        total_cost += cost

        if kind == "application":
            request_latencies.append(latency)
        if kind == "postcondition":
            postcondition_qualities.append(quality)
        if kind in INFRA_KINDS:
            infra_count += 1
            if status == "error":
                infra_errors += 1

    for trace_id, trace_records in by_trace.items():
        trace_ids = {record["span_id"] for record in trace_records}
        kinds = {record["kind"] for record in trace_records}
        if not required_kinds.issubset(kinds):
            raise ValueError("missing_required_span_kind")
        roots = [record for record in trace_records if record["kind"] == "application"]
        posts = [record for record in trace_records if record["kind"] == "postcondition"]
        if len(roots) != 1 or roots[0]["parent_span_id"] is not None:
            raise ValueError("application_root_invalid")
        if len(posts) != 1:
            raise ValueError("postcondition_count_invalid")
        for record in trace_records:
            if record["kind"] != "application":
                parent_id = record["parent_span_id"]
                if parent_id not in trace_ids:
                    raise ValueError("parent_not_in_trace")
                if parent_id == record["span_id"]:
                    raise ValueError("self_parent")
            if "retry_of" in record:
                target_id = record["retry_of"]
                if not isinstance(target_id, str) or target_id not in trace_ids:
                    raise ValueError("retry_target_missing")
                target = ids[target_id]
                if positions[target_id] >= positions[record["span_id"]]:
                    raise ValueError("retry_target_not_earlier")
                if target["kind"] != record["kind"] or target["trace_id"] != trace_id:
                    raise ValueError("retry_target_mismatch")
                if target["status"] != "error":
                    raise ValueError("retry_target_not_failed")

    if len(postcondition_qualities) != len(by_trace):
        raise ValueError("quality_not_one_per_trace")
    if infra_count == 0:
        raise ValueError("no_infrastructure_spans")

    span_p50 = percentile(span_latencies, 0.50)
    request_p50 = percentile(request_latencies, 0.50)
    quality = sum(postcondition_qualities) / len(postcondition_qualities)

    reported = (
        ("reported_span_p50_ms", span_p50),
        ("reported_request_p50_ms", request_p50),
        ("reported_quality", quality)
    )
    for field, computed in reported:
        claimed = number(candidate.get(field), field)
        if abs(claimed - computed) > TOLERANCE:
            raise ValueError(field + "_mismatch")

    return {
        "request_p50": request_p50,
        "request_p95": percentile(request_latencies, 0.95),
        "request_p99": percentile(request_latencies, 0.99),
        "span_p50": span_p50,
        "span_p95": percentile(span_latencies, 0.95),
        "span_p99": percentile(span_latencies, 0.99),
        "quality": quality,
        "infra": 1.0 - infra_errors / infra_count,
        "cost": total_cost
    }


def evaluate_candidate(candidate, required_kinds):
    reasons = []
    for field in ("privacy_redaction", "export_otlp", "tenant_isolation"):
        if candidate.get(field) is not True:
            reasons.append(field)
    try:
        measures = validate_records(candidate, required_kinds)
    except (KeyError, TypeError, ValueError) as error:
        reasons.append(str(error))
        measures = None
    if reasons:
        return False, reasons, None
    measures["score"] = (
        0.50 * measures["quality"]
        + 0.30 * measures["infra"]
        + 0.20 * (1.0 - measures["cost"])
    )
    return True, [], measures


def apply_negative(base, mutation):
    candidate = copy.deepcopy(base)
    operation = mutation["op"]
    if operation == "set_candidate":
        candidate[mutation["field"]] = mutation["value"]
        return candidate
    records = candidate["records"]
    index = next(i for i, record in enumerate(records)
                 if isinstance(record, dict) and record.get("span_id") == mutation["span_id"])
    if operation == "set_record":
        records[index][mutation["field"]] = mutation["value"]
    elif operation == "remove_record":
        records.pop(index)
    elif operation == "duplicate_record":
        records.append(copy.deepcopy(records[index]))
    elif operation == "replace_record":
        records[index] = mutation["value"]
    else:
        raise ValueError("unknown_negative_operation")
    return candidate


def render(data):
    required_kinds = set(data["required_span_kinds"])
    assert required_kinds == REQUIRED_KINDS
    assert percentile([100, 120, 150, 200, 400], 0.50) == 150
    assert percentile([100, 120, 150, 200, 400], 0.95) == 360
    assert percentile([100, 120, 150, 200, 400], 0.99) == 392

    lines = []
    passing = []
    for candidate in data["candidates"]:
        accepted, reasons, measures = evaluate_candidate(candidate, required_kinds)
        if not accepted:
            lines.append("candidate={} hard_gate=REJECT reasons={}".format(
                candidate.get("name", "UNKNOWN"), ",".join(reasons)))
            continue
        lines.append(
            "candidate={name} hard_gate=PASS request_p50_ms={request_p50:.3f} "
            "request_p95_ms={request_p95:.3f} request_p99_ms={request_p99:.3f} "
            "span_p50_ms={span_p50:.3f} span_p95_ms={span_p95:.3f} "
            "span_p99_ms={span_p99:.3f} quality={quality:.3f} infra={infra:.3f} "
            "cost_usd={cost:.3f} score={score:.3f}".format(
                name=candidate["name"], **measures))
        passing.append((measures["score"], candidate["name"]))

    lines.append("selected=" + (max(passing)[1] if passing else "NONE"))

    base = data["candidates"][0]
    for name, mutation in data["negative_cases"].items():
        negative = apply_negative(base, mutation)
        accepted, _, _ = evaluate_candidate(negative, required_kinds)
        assert not accepted, "supplied negative case was accepted: " + name
        lines.append("negative={} result=REJECT".format(name))
    return "\n".join(lines)


def main():
    if len(sys.argv) not in (2, 3) or (len(sys.argv) == 3 and sys.argv[2] != "--explore"):
        raise SystemExit("usage: python3 evaluate.py fixture.json [--explore]")
    with open(sys.argv[1], encoding="utf-8") as handle:
        data = json.load(handle)
    output = render(data)
    if len(sys.argv) == 2:
        assert output == EXPECTED_STDOUT, "exact expected stdout changed"
    print(output)


if __name__ == "__main__":
    main()
